private static AggregateExec aggExec(
        Aggregate aggregate,
        PhysicalPlan child,
        AggregatorMode aggMode,
        List<Attribute> intermediateAttributes
    ) {
        return new AggregateExec(
            aggregate.source(),
            child,
            aggregate.groupings(),
            aggregate.aggregates(),
